set search_path=public,extensions,auth;set timezone='UTC';
select jsonb_object_agg(k,v)from(select 'collect_receipt_operations.requests' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['request_id','principal_id','action','request_sha256','input','issued_at','recorded_at','result']))j from collect_receipt_operations.requests t)s union all select 'collect_receipt_operations.owner_requests' k,jsonb_build_object('rows',count(*),'sha256',encode(extensions.digest(coalesce(string_agg(j::text,E'\n' order by j::text),''),'sha256'),'hex'))v from(select(select jsonb_object_agg(k,v)from jsonb_each(to_jsonb(t))x(k,v)where k=any(array['request_id','actor_id','session_id','action','input','result','recorded_at','expires_at']))j from collect_receipt_operations.owner_requests t)s)s;